class MusicDirector:
    """Decides which music track should play from the game situation. Pure logic (no audio, no I/O) so it is unit
testable. Returns an ordered preference list; the manager plays the first track whose file exists.

Rules: victory and defeat share the end-screen track; Palantir (wave 100 or Palantir alive) overrides everything; a MOAB-class
boss on the field uses the boss theme; otherwise the era battle track (O(N^N) override, waves 60+ late, else
normal). The boss theme is held a few seconds after the last boss dies to avoid flip-flopping."""
    def __init__(self):
        self.held = None
        self.held_until = (-1)
        pass
    def choose(self, victory, defeat, wave, onn, palantir, boss, now):
        """@param victory  the game is won
@param defeat   the game is lost
@param wave     current wave number (0 before the first wave)
@param onn      O(N^N) difficulty
@param palantir Palantir is alive
@param boss     any other boss is alive
@param now      monotonically increasing seconds
@return preference-ordered tracks"""
        if victory or defeat:
            return [Track.END]
        battle = MusicDirector.battle_chain(wave, onn)
        want = None
        if palantir or (wave >= MusicDirector.FINAL_WAVE):
            want = MusicDirector.concat([Track.PALANTIR, Track.BOSS], battle)
        elif boss:
            want = MusicDirector.concat([Track.BOSS], battle)
        if want is not None:
            self.held = want
            self.held_until = (now + MusicDirector.BOSS_HOLD_SECONDS)
            return want
        if (self.held is not None) and (now < self.held_until):
            return self.held
        self.held = None
        return battle
    @staticmethod
    def battle_chain(wave, onn):
        """The era battle track preference chain."""
        if onn:
            return [Track.BATTLE_ONN, Track.BATTLE_LATE, Track.BATTLE]
        if wave >= MusicDirector.LATE_WAVE:
            return [Track.BATTLE_LATE, Track.BATTLE]
        return [Track.BATTLE]
    @staticmethod
    def concat(a, b):
        r = ([None] * (len(a) + len(b)))
        _j.array_copy(a, 0, r, 0, len(a))
        _j.array_copy(b, 0, r, len(a), len(b))
        return r


